"use client";
import {useState} from "react";
import {WAIVER_CONSENT} from "@/lib/waiver-consent";
export function WaiverSigner({quoteId,quoteHash,documents,payMode}:{quoteId:string;quoteHash:string;documents:{id:string;title:string;signed:boolean}[];payMode:string}){
 const [signed,setSigned]=useState(documents.filter(doc=>doc.signed).map(doc=>doc.id)),[error,setError]=useState(""),[pending,setPending]=useState(false);
 const complete=documents.every(doc=>signed.includes(doc.id));
 return <div className="space-y-6"><p>Review and sign each required waiver before continuing to payment. A copy will remain available with this booking.</p>{documents.map(doc=><section key={doc.id} className="rounded-2xl border bg-white p-5"><h2 className="text-xl font-semibold">{doc.title}</h2><a className="mt-2 inline-block text-sm underline" href={`/api/waivers/${doc.id}?quoteId=${quoteId}`} target="_blank" rel="noreferrer">Open or download full waiver</a><iframe title={`${doc.title} document`} src={`/api/waivers/${doc.id}?quoteId=${quoteId}`} className="mt-4 h-[480px] w-full rounded-xl border"/>{signed.includes(doc.id)?<p role="status" className="mt-4 font-semibold text-green-800">Signed electronically</p>:<form className="mt-4 space-y-4" onSubmit={async event=>{event.preventDefault();const form=new FormData(event.currentTarget);setPending(true);setError("");try{const response=await fetch(`/api/waivers/sign/${quoteId}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({waiverId:doc.id,quoteHash,signerName:form.get("signerName"),consent:form.get("consent")==="on"})}),data=await response.json();if(!response.ok)throw new Error(data.error);setSigned(current=>[...current,doc.id]);}catch(e){setError(e instanceof Error?e.message:"Could not sign waiver.");}finally{setPending(false);}}}><label className="grid gap-2 text-sm font-semibold">Your full legal name<input name="signerName" autoComplete="name" required minLength={2} maxLength={120} className="rounded-xl border px-3 py-3"/></label><label className="flex items-start gap-3 text-sm"><input type="checkbox" name="consent" required className="mt-1"/><span>{WAIVER_CONSENT}</span></label><button disabled={pending} className="rounded-full bg-[#493e46] px-5 py-3 text-white" type="submit">{pending?"Signing…":"Sign waiver"}</button></form>}</section>)}{error&&<p role="alert" className="text-red-700">{error}</p>}<form action={`/waivers/continue/${quoteId}`} method="post"><input type="hidden" name="payMode" value={payMode}/><button disabled={!complete||pending} className="rounded-full bg-[#493e46] px-6 py-3 text-white disabled:opacity-40">Continue to payment</button></form></div>;
}
